const item = $input.first().json;
const b = item.body || {};
const errors = [];
for (const f of ['business_id', 'from_email', 'body']) {
  if (!b[f] || typeof b[f] !== 'string' || !b[f].trim()) errors.push('missing or empty: ' + f);
}
if (b.from_email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(b.from_email.trim())) {
  errors.push('invalid from_email');
}
const rand = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
return [{ json: {
  ok: errors.length === 0,
  errors,
  business_id: (b.business_id || '').trim(),
  lead_id: 'lead_' + rand(),
  trace_id: 'trc_' + rand(),
  channel: (b.channel || 'webhook').trim(),
  from_email: (b.from_email || '').trim().toLowerCase(),
  from_name: b.from_name || null,
  subject: b.subject || null,
  body_text: b.body || '',
  received_at: b.received_at || null,
  raw: b
} }];
